void process_sas_commands(void) {
    struct sas_command *cmd, *next;
    struct sas_task *task;

    list_for_each_entry_safe(cmd, next, &command_list, list_entry) {
        task = cmd->task;
        if (task->reset_needed) {
            if (task->state == SAS_TASK_STATE_LU_RESET) {
                if (recover_logical_unit(task)) {
                    log_message("Recovered logical unit for task %p", task);
                } else {
                    log_error("Failed to recover logical unit for task %p", task);
                }
            } else if (task->state == SAS_TASK_STATE_I_T_RESET) {
