                    log_message("Recovered I_T connection for task %p", task);
                } else {
                    log_error("Failed to recover I_T connection for task %p", task);
                }
            } else {
                log_message("Task reset not required for state %d", task->state);
            }

            spin_lock(&task->state_lock);
            task->reset_needed = false;
