void process_sas_commands(void) {
    struct sas_command *cmd, *tmp;

    list_for_each_entry_safe(cmd, tmp, &command_list, list_entry) {
        struct sas_task *task = cmd->task;
        unsigned long flags;

        if (!task)
            continue;

        spin_lock_irqsave(&task->state_lock, flags);
        if (task->reset_required) {
            spin_unlock_irqrestore(&task->state_lock, flags);

            if (task->state == SAS_TASK_STATE_LU_RESET) {
                pr_info("Attempting LU recovery for task %p\n", task);
                if (!recover_logical_unit(task)) {
                    pr_err("Failed to recover logical unit for task %p\n", task);
                }
            } else if (task->state == SAS_TASK_STATE_I_T_RESET) {
                pr_info("Attempting I_T recovery for task %p\n", task);
                if (!recover_i_t_connection(task)) {
                    pr_err("Failed to recover I_T connection for task %p\n", task);
                }
            } else {
                pr_err("Unknown reset state for task %p: %d\n", task, task->state);
            }

            spin_lock_irqsave(&task->state_lock, flags);
            task->reset_required = 0;
        }
        spin_unlock_irqrestore(&task->state_lock, flags);

        list_del(&cmd->list_entry);
        clear_command_queue(cmd);
        sas_free_command(cmd);
    }
}

void process_sas_commands(void) {
    struct sas_command *cmd, *tmp;
    struct sas_task *task;
    int recovery_needed;

    list_for_each_entry_safe(cmd, tmp, &command_list, list) {
        task = cmd->task;
        recovery_needed = task->reset_needed;

        if (recovery_needed) {
            spin_lock_irq(&task->state_lock);

            if (task->state == SAS_TASK_STATE_RESET) {
                if (task->is_lu_device) {
                    if (recover_lu(task)) {
                        log_info("Logical Unit recovery successful for task %p", task);
                        task->reset_needed = 0;
                    } else {
                        log_error("Failed to recover Logical Unit for task %p", task);
                    }
                } else if (task->is_it_connection) {
                    if (recover_it_connection(task)) {
                        log_info("I_T connection recovery successful for task %p", task);
                        task->reset_needed = 0;
                    } else {
                        log_error("Failed to recover I_T connection for task %p", task);
                    }
                }

                if (task->reset_needed == 0) {
                    clear_task_queues(task);
                }
            }

            spin_unlock_irq(&task->state_lock);
        }

        if (!task->reset_needed) {
            list_del(&cmd->list);
            kfree(cmd);
        }
    }
}

void process_sas_commands(void) {
    struct sas_command *cmd, *tmp;

    list_for_each_entry_safe(cmd, tmp, &command_list, entry) {
        struct sas_task *task = cmd->task;
        unsigned long flags;

        if (task->state == SAS_TASK_RESET_REQUIRED) {
            spin_lock_irqsave(&task->state_lock, flags);

            if (task->state == SAS_TASK_RESET_REQUIRED) {
                if (task->is_lu_device) {
                    if (recover_logical_unit(task)) {
                        log_message("Recovered logical unit for task %p", task);
                        task->state = SAS_TASK_ACTIVE;
                    } else {
                        log_error("Failed to recover logical unit for task %p", task);
                    }
                } else if (task->is_it_connection) {
                    if (recover_it_connection(task)) {
                        log_message("Recovered I_T connection for task %p", task);
                        task->state = SAS_TASK_ACTIVE;
                    } else {
                        log_error("Failed to recover I_T connection for task %p", task);
                    }
                } else {
                    log_error("Unknown device type for task %p", task);
                }
            }

            spin_unlock_irqrestore(&task->state_lock, flags);
        }

        if (task->state == SAS_TASK_COMPLETED ||
            task->state == SAS_TASK_FAILED ||
            task->state == SAS_TASK_RESET_REQUIRED) {
            clear_command_queue(cmd);
            list_del(&cmd->entry);
            free_sas_command(cmd);
        }
    }
}

void process_sas_commands(void) {
    struct sas_command *cmd, *tmp;
    struct sas_task *task;

    list_for_each_entry_safe(cmd, tmp, &command_list, list_entry) {
        task = cmd->task;
        unsigned long flags;

        if (task->reset_required) {
            spin_lock_irqsave(&task->state_lock, flags);
            if (task->state == SAS_TASK_STATE_RESETTING ||
                task->state == SAS_TASK_STATE_DONE) {
                spin_unlock_irqrestore(&task->state_lock, flags);
                continue;
            }

            task->state = SAS_TASK_STATE_RESETTING;
            spin_unlock_irqrestore(&task->state_lock, flags);

            if (task->lu_reset_required) {
                int ret = recover_logical_unit(cmd->device);
                if (ret != 0) {
                    dev_err(&cmd->device->dev, "Failed to recover logical unit for device %s\n",
                            dev_name(&cmd->device->dev));
                } else {
                    dev_info(&cmd->device->dev, "Logical unit recovery successful for device %s\n",
                             dev_name(&cmd->device->dev));
                }
            } else {
                int ret = recover_i_t_connection(cmd->device);
                if (ret != 0) {
                    dev_err(&cmd->device->dev, "Failed to recover I_T connection for device %s\n",
                            dev_name(&cmd->device->dev));
                } else {
                    dev_info(&cmd->device->dev, "I_T connection recovery successful for device %s\n",
                             dev_name(&cmd->device->dev));
                }
            }

            spin_lock_irqsave(&task->state_lock, flags);
            task->reset_required = 0;
            task->state = SAS_TASK_STATE_IDLE;
            spin_unlock_irqrestore(&task->state_lock, flags);
        }

        clear_command_queue(cmd);
        list_del(&cmd->list_entry);
        kfree(cmd);
    }
}
